 function purge(cause:unknown){setData(null);setDraft(null);setEditing(false);setError(cause instanceof Error?cause.message:'Board access was cleared.');if(cause instanceof ApiError&&cause.status===401&&!notified.current){notified.current=true;live.current.onUnauthorized();}}
